const date=value=>value?new Date(value).toLocaleString():"—";
const relativeDate=value=>{if(!value)return"—";const when=new Date(value);const seconds=Math.round((when.getTime()-Date.now())/1000);const absolute=Math.abs(seconds);if(absolute<45)return"Just now";const units=[[60,"minute"],[60,"hour"],[24,"day"],[7,"week"]];let amount=seconds;let unit="second";for(const[step,next]of units){if(Math.abs(amount)<step)break;amount=Math.round(amount/step);unit=next}if(Math.abs(amount)>=4&&unit==="week")return when.toLocaleDateString();return new Intl.RelativeTimeFormat(undefined,{numeric:"auto"}).format(amount,unit)};
