function previewStageMarkup(version,color){if(!version)return `<div id="colorPreviewViewport" class="color-preview-viewport"><div class="detail-placeholder"><strong>${esc(color.name)}</strong><small>No reference image yet</small></div></div>`;const display=`/api/display/${version.id}`;const thumb=`/api/previews/${version.id}`;const full=`/api/assets/${version.id}`;return `<div id="colorPreviewViewport" class="color-preview-viewport"><p id="previewLoading" class="preview-loading" role="status">Loading full image…</p><img id="colorPreviewImage" src="${display}" alt="${esc(color.name)} ${esc(version.originalFilename||"")}" decoding="async" draggable="false"></div><div class="preview-zoom" role="group" aria-label="Zoom"><button id="previewZoomOut" type="button" aria-label="Zoom out" disabled>−</button><output id="previewZoomLevel" for="previewZoomOut previewZoomIn">100%</output><button id="previewZoomIn" type="button" aria-label="Zoom in" disabled>+</button></div><div id="previewNavigator" class="preview-navigator" hidden><img id="previewNavigatorImage" alt="" src="${thumb}" draggable="false"><div id="previewNavigatorFrame" class="preview-navigator-frame" tabindex="0" aria-label="Drag to move the zoomed area"></div></div>${previewActionBar(full)}`}
function previewFitScale(naturalWidth,naturalHeight,stageWidth,stageHeight){if(!naturalWidth||!naturalHeight||!stageWidth||!stageHeight)return 1;return Math.min(stageWidth/naturalWidth,stageHeight/naturalHeight)}
