  layer = document.createElement("div");
  layer.className = "preview-compare-stage";
  layer.style.setProperty("--compare-split", "50%");
  layer.innerHTML = `<img class="preview-compare-base" alt=""><div class="preview-compare-clip"><img class="preview-compare-over" alt=""></div><div class="preview-compare-split"></div><p class="preview-compare-status" role="status" hidden>This image could not be displayed.</p>`;
