function referenceTypeBase(reference){const base=String(reference.label||reference.kind||"").replace(/(?:\s+reference)+$/i,"").trim().toUpperCase();return base==="QUICK"?"CROP":base}
function referenceType(reference){return `${referenceTypeBase(reference)} Reference`}
function referenceLabel(reference){return referenceType(reference)}
function groupedReferences(color){const groups=new Map();for(const reference of color?.references||[]){if(!groups.has(reference.id))groups.set(reference.id,{...reference,versions:[]});const group=groups.get(reference.id);if(reference.version&&!group.versions.some(version=>version.id===reference.version.id))group.versions.push(reference.version)}return [...groups.values()].map(reference=>({...reference,versions:reference.versions.sort((a,b)=>b.number-a.number)}))}
function editReferenceMarkup(reference,index){return `<section class="reference-editor" data-reference-editor="${reference.id}" ${index?"hidden":""}><label>Reference instructions<textarea name="reference:${reference.id}:instructions" maxlength="5000" placeholder="Add guidance specific to this reference...">${esc(reference.instructions||"")}</textarea></label><div class="version-editor-heading"><div><strong>Version history</strong><small>Edit the filename and review note for each uploaded file.</small></div></div><div class="version-editor-list">${reference.versions.map(version=>`<article class="version-editor"><a href="/api/assets/${version.id}" target="_blank" rel="noopener" aria-label="Open version ${version.number}"><img src="/api/previews/${version.id}" alt="" loading="lazy" decoding="async"></a><div class="version-editor-content"><div class="version-editor-meta"><strong>Version ${version.number}</strong><span class="pill ${version.status.toLowerCase()}">${esc(version.status)}</span></div><div class="editor-field-grid"><label>Display filename<input name="version:${version.id}:filename" value="${esc(version.originalFilename)}" maxlength="255" required></label><label>Version note<input name="version:${version.id}:note" value="${esc(version.uploadNote||"")}" maxlength="5000" placeholder="What changed in this version?"></label></div><small class="version-file-hint">Keep the original file extension. · Uploaded ${date(version.createdAt)}</small></div></article>`).join("")||'<div class="editor-empty">No versions uploaded yet.</div>'}</div></section>`}
colorModal=function(color,clientId){if(!color){openModal({eyebrow:"NEW COLOR",title:"Add approved color",body:`<label>Color name<input name="name" required></label><label>Pantone<input name="colorCode"></label><label>Retouching instructions<textarea name="instructions" placeholder="Usage notes, finish, matching guidance..."></textarea></label>`,submit:"Add color",onSubmit:async form=>{const data=Object.fromEntries(form);data.clientId=clientId;await api("/api/client/colors",{method:"POST",body:JSON.stringify(data)});toast("Color added");await renderLibrary(clientId)}});return}const references=groupedReferences(color);const referenceNav=references.length?`<div class="reference-editor-navigation" aria-label="Choose a reference"><div class="reference-editor-tabs" role="tablist">${references.map((reference,index)=>`<button class="reference-editor-tab ${index?"":"is-active"}" type="button" role="tab" aria-selected="${index?"false":"true"}" data-reference-tab="${reference.id}"><span>${esc(referenceType(reference))}</span><small>${reference.versions.length} version${reference.versions.length===1?"":"s"}</small></button>`).join("")}</div><label class="reference-editor-select-label">Reference type<select id="referenceEditorSelect">${references.map(reference=>`<option value="${reference.id}">${esc(referenceType(reference))} · ${reference.versions.length} version${reference.versions.length===1?"":"s"}</option>`).join("")}</select></label></div>`:"";openModal({eyebrow:"EDIT DETAILS",title:color.name,body:`<div class="edit-details-form"><section class="edit-section color-editor-section"><header class="edit-section-heading"><div><span class="editor-section-icon">C</span><div><strong>Overall color swatch</strong><small>Core information shown across Approved colors.</small></div></div></header><div class="editor-field-grid"><label>Color name<input name="name" value="${esc(color.name)}" required></label><label>Pantone<input name="colorCode" value="${esc(color.colorCode||"")}" placeholder="Optional"></label><label><span>Hex code <span class="muted" title="https://registry.color.org/rgb-registry/adobergb">Adobe RGB (1998)</span></span><input name="hexCode" value="${esc(color.hexCode||"")}" placeholder="#E76223" maxlength="7" spellcheck="false" autocomplete="off"></label></div><label>Overall instructions<textarea name="instructions" placeholder="Usage notes, finish, matching guidance...">${esc(color.instructions||"")}</textarea></label></section><section class="edit-section"><header class="edit-section-heading"><div><span class="editor-section-icon">R</span><div><strong>References and versions</strong><small>Choose a reference type, then edit its details and version history.</small></div></div><span class="editor-count">${references.length} reference${references.length===1?"":"s"}</span></header>${referenceNav}<div class="reference-editor-list">${references.map(editReferenceMarkup).join("")||'<div class="editor-empty">No references yet. Use Upload reference to add the first one.</div>'}</div></section></div>`,submit:"Save all changes",onSubmit:async form=>{const hexRaw=String(form.get("hexCode")||"").trim();if(hexRaw&&!/^#?(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(hexRaw))throw new Error("Enter a hex code such as #E76223.");if(!await confirmAction({eyebrow:"SAVE EDITS",title:`Save changes to ${color.name}?`,message:"This updates the color details, reference instructions, and version notes.",confirmLabel:"Save changes",icon:"✓"}))throw cancelledEdit();const colorData={name:form.get("name"),colorCode:form.get("colorCode"),hexCode:hexRaw,instructions:form.get("instructions")};await api(`/api/client/colors/${color.id}`,{method:"PATCH",body:JSON.stringify(colorData)});const updates=[];for(const reference of references){const instructions=String(form.get(`reference:${reference.id}:instructions`)||"");if(instructions!==String(reference.instructions||""))updates.push(api(`/api/client/references/${reference.id}`,{method:"PATCH",body:JSON.stringify({instructions})}));for(const version of reference.versions){const originalFilename=String(form.get(`version:${version.id}:filename`)||"");const uploadNote=String(form.get(`version:${version.id}:note`)||"");if(originalFilename!==String(version.originalFilename||"")||uploadNote!==String(version.uploadNote||""))updates.push(api(`/api/client/versions/${version.id}`,{method:"PATCH",body:JSON.stringify({originalFilename,uploadNote})}))}}await Promise.all(updates);toast("Color, references, and versions updated");const reopenPage=state.detailColorId===color.id;await renderLibrary(state.user.selectedClientId||clientId);if(reopenPage)renderColorPage(color.id,{pushHistory:false})}});const showReference=id=>{document.querySelectorAll("[data-reference-editor]").forEach(editor=>editor.hidden=editor.dataset.referenceEditor!==id);document.querySelectorAll("[data-reference-tab]").forEach(tab=>{const active=tab.dataset.referenceTab===id;tab.classList.toggle("is-active",active);tab.setAttribute("aria-selected",String(active))});const select=$("#referenceEditorSelect");if(select)select.value=id};document.querySelectorAll("[data-reference-tab]").forEach(tab=>tab.onclick=()=>showReference(tab.dataset.referenceTab));const referenceSelect=$("#referenceEditorSelect");if(referenceSelect)referenceSelect.onchange=()=>showReference(referenceSelect.value)};
async function versionAction(id,action,reopenColorId){const confirmations={approve:{eyebrow:"APPROVE VERSION",title:"Approve this image version?",message:"This version will become the active approved reference and replace the currently approved version.",confirmLabel:"Approve version",icon:"✓"},unapprove:{eyebrow:"UNAPPROVE VERSION",title:"Unapprove this image version?",message:"This image will remain in version history, but it will no longer be the active approved reference.",confirmLabel:"Unapprove version",icon:"↶"},remove:{eyebrow:"REMOVE VERSION",title:"Remove this image version?",message:"This version will be permanently removed from Approved colors. If it is the last image, its reference type will also be removed.",confirmLabel:"Remove version",tone:"danger",icon:"!"}};if(!await confirmAction(confirmations[action]||{title:"Continue with this action?",message:"Please confirm before continuing."}))return;const url=action==="remove"?`/api/client/versions/${id}`:`/api/client/versions/${id}/${action}`;const result=await api(url,{method:action==="remove"?"DELETE":"POST",body:action==="remove"?undefined:"{}"});toast(result.sync?.status==="FAILED"?`Approved, but local sync failed: ${result.sync.error}`:`Version ${action}d`);await renderLibrary(state.user.selectedClientId);if(reopenColorId)showColorDetail(reopenColorId,{updateHash:false})}
async function deleteColor(id){const color=state.catalog?.colors.find(item=>item.id===id);if(!await confirmAction({eyebrow:"DELETE COLOR",title:`Delete ${color?.name||"this color"}?`,message:"This permanently deletes the color, its references, its files, and any request linked to it. This cannot be undone.",confirmLabel:"Delete this color",tone:"danger",icon:"!",challenge:"delete"}))return;await api(`/api/client/colors/${id}/delete`,{method:"POST",body:JSON.stringify({confirmation:"delete"})});toast("Color deleted");if(state.detailColorId===id)return returnToLibrary({replaceHistory:true,allowOpenEdit:true});await renderLibrary(state.user.selectedClientId)}
